INSERT INTO "VocationalSchool" (slug, "name", "nameJa", "category", "location", "tuition", "totalTwoYears", "highlights", "employmentRate", "employmentRateDetail", "paymentTerm", "degreeAwarded", "attendanceRequirement", "featuresJson", "programsJson", "tuitionBreakdownJson", "suitableForJson", "scholarshipsJson") VALUES ('tokyo-seika', '东京制菓学校', '東京製菓学校', '制果 / 甜点 / 面包', '东京都新宿区高田马场1-14-1', '2027年度留学生募集要项已公布，学费和诸费用按昼间/夜间及洋菓子、和菓子、面包学科区分；旧统一年费与就业率已删除。', '昼夜课程均为2年，费用按2027要项逐科确认。', '2027留学生要项已更新日语能力证明范围；学费包含材料费，但部分研修等可能另计。', NULL, '官网未提供可用于本站的统一就业率统计；旧就业率和定点招聘说法已删除。', '按2027募集要项和合格通知。', '专业士称号与资格依课程认定。', '按2027留学生募集要项。', '["洋菓子","和菓子","面包","昼间与夜间2年制"]'::jsonb, '[{"name":"洋菓子／和菓子／面包","description":"昼间本科和夜间专科均为2年制。","duration":"2年","totalCost":"按2027要项"}]'::jsonb, '{"enrollmentFee":"按2027留学生募集要项第17页及志望学科确认","admissionFee":"按2027留学生募集要项第17页及志望学科确认","annualTuition":"按2027留学生募集要项第17页及志望学科确认","facilitiesFee":"按2027留学生募集要项第17页及志望学科确认","practiceMaterialsFee":"按2027留学生募集要项第17页及志望学科确认","totalFirstYear":"按2027留学生募集要项第17页及志望学科确认"}'::jsonb, '["西点","和菓子","面包制作"]'::jsonb, '["N1且符合条件的留学生进学应援制度可从实习费减免100,000日元，名额有限。"]'::jsonb) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "category" = EXCLUDED."category", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "totalTwoYears" = EXCLUDED."totalTwoYears", "highlights" = EXCLUDED."highlights", "employmentRate" = EXCLUDED."employmentRate", "employmentRateDetail" = EXCLUDED."employmentRateDetail", "paymentTerm" = EXCLUDED."paymentTerm", "degreeAwarded" = EXCLUDED."degreeAwarded", "attendanceRequirement" = EXCLUDED."attendanceRequirement", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "tuitionBreakdownJson" = EXCLUDED."tuitionBreakdownJson", "suitableForJson" = EXCLUDED."suitableForJson", "scholarshipsJson" = EXCLUDED."scholarshipsJson";
INSERT INTO "VocationalSchool" (slug, "name", "nameJa", "category", "location", "tuition", "totalTwoYears", "highlights", "employmentRate", "employmentRateDetail", "paymentTerm", "degreeAwarded", "attendanceRequirement", "featuresJson", "programsJson", "tuitionBreakdownJson", "suitableForJson", "scholarshipsJson") VALUES ('nippon-photo', '日本写真映像专门学校', '日本写真映像専門学校', '写真 / 映像 / 放送', '大阪府大阪市东住吉区矢田1-5-9', '2027费用按摄影、影像或夜间课程确认；学校当前不接收需要由本校取得留学签证的昼间留学生。', '昼间课程虽为2年，但新留学生签证申请目前不受理；夜间课程为1年。', '官网明确目前不接收需要留学签的新生；已在其他大学、短大或专门学校持有效留学签者，仅可在其在籍与签证有效期内以Wスクール方式申请夜间课程。', NULL, '官网未提供可用于本站的统一就业率统计；旧就业率和定点招聘说法已删除。', '按2027要项。', '夜间1年课程不据此声称授予专业士。', '须维持可合法在籍的在留资格；具体申请条件见外国籍募集要项。', '["摄影","影像制作","夜间摄影课程","不能由本校办理留学签"]'::jsonb, '[{"name":"Photo Fine夜间课程","description":"外国籍申请者须在日本、具N2等条件及国内保证人；本校不能办理留学签。","duration":"1年（夜间）","totalCost":"按2027要项"}]'::jsonb, '{"enrollmentFee":"按2027募集要项及可申请课程确认","admissionFee":"按2027募集要项及可申请课程确认","annualTuition":"按2027募集要项及可申请课程确认","facilitiesFee":"按2027募集要项及可申请课程确认","practiceMaterialsFee":"按2027募集要项及可申请课程确认","totalFirstYear":"按2027募集要项及可申请课程确认"}'::jsonb, '["已在日本且具备适用在留资格的夜间摄影学习者"]'::jsonb, '["本批未核实留学生专用奖学金。"]'::jsonb) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "category" = EXCLUDED."category", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "totalTwoYears" = EXCLUDED."totalTwoYears", "highlights" = EXCLUDED."highlights", "employmentRate" = EXCLUDED."employmentRate", "employmentRateDetail" = EXCLUDED."employmentRateDetail", "paymentTerm" = EXCLUDED."paymentTerm", "degreeAwarded" = EXCLUDED."degreeAwarded", "attendanceRequirement" = EXCLUDED."attendanceRequirement", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "tuitionBreakdownJson" = EXCLUDED."tuitionBreakdownJson", "suitableForJson" = EXCLUDED."suitableForJson", "scholarshipsJson" = EXCLUDED."scholarshipsJson";
INSERT INTO "VocationalSchool" (slug, "name", "nameJa", "category", "location", "tuition", "totalTwoYears", "highlights", "employmentRate", "employmentRateDetail", "paymentTerm", "degreeAwarded", "attendanceRequirement", "featuresJson", "programsJson", "tuitionBreakdownJson", "suitableForJson", "scholarshipsJson") VALUES ('chuo-kogyo', '中央工学校', '中央工学校', '建筑 / 土木 / CAD / 设计', '东京都北区王子本町1-26-17', '2027留学生费用须按中央工学校具体学科募集要项确认；旧统一费用、就业率和大手企业录用宣传已删除。', '建筑、土木、测量等课程年限不同，须逐科确认。', '保留中央工学校单一官方主体，不再混用中央工学校集团内其他学校的课程与费用。', NULL, '官网未提供可用于本站的统一就业率统计；旧就业率和定点招聘说法已删除。', '按2027要项。', '专业士或高度专业士依具体课程认定。', '按2027留学生要项。', '["建筑","土木与测量","机械与CAD","王子校区"]'::jsonb, '[{"name":"建筑／土木／测量／机械相关学科","description":"课程、年限、资格和费用以2027留学生募集要项为准。","duration":"依学科","totalCost":"待确认"}]'::jsonb, '{"enrollmentFee":"按2027留学生募集要项及学科确认","admissionFee":"按2027留学生募集要项及学科确认","annualTuition":"按2027留学生募集要项及学科确认","facilitiesFee":"按2027留学生募集要项及学科确认","practiceMaterialsFee":"按2027留学生募集要项及学科确认","totalFirstYear":"按2027留学生募集要项及学科确认"}'::jsonb, '["建筑","土木测量","机械CAD"]'::jsonb, '["奖学金与减免按当期募集要项。"]'::jsonb) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "category" = EXCLUDED."category", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "totalTwoYears" = EXCLUDED."totalTwoYears", "highlights" = EXCLUDED."highlights", "employmentRate" = EXCLUDED."employmentRate", "employmentRateDetail" = EXCLUDED."employmentRateDetail", "paymentTerm" = EXCLUDED."paymentTerm", "degreeAwarded" = EXCLUDED."degreeAwarded", "attendanceRequirement" = EXCLUDED."attendanceRequirement", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "tuitionBreakdownJson" = EXCLUDED."tuitionBreakdownJson", "suitableForJson" = EXCLUDED."suitableForJson", "scholarshipsJson" = EXCLUDED."scholarshipsJson";
INSERT INTO "VocationalSchool" (slug, "name", "nameJa", "category", "location", "tuition", "totalTwoYears", "highlights", "employmentRate", "employmentRateDetail", "paymentTerm", "degreeAwarded", "attendanceRequirement", "featuresJson", "programsJson", "tuitionBreakdownJson", "suitableForJson", "scholarshipsJson") VALUES ('tokyo-hoiku', '东京保育专门学校', '東京保育専門学校', '保育 / 幼儿教育 / 福祉', '东京都杉并区高圆寺南2-32-30', '2027年度募集要项已公布；学费按昼间2年制与夜间3年制分别计算，本批未取得完整缴费表，旧统一低价与就业率已删除。', '留学在留资格仅可申请昼间部；具体费用按2027要项。', '2027要项明确：留学在留资格仅可申请昼间部且为若干名；校方同时提醒，毕业后以幼稚园教谕或保育士身份取得相应就劳在留资格目前较困难。', NULL, '学校明确提示外国籍毕业生的保育/幼教就劳在留资格限制，不使用旧就业率宣传。', '按2027要项。', '专业士（保育专业课程），并可取得校方列示的保育士与幼稚园教谕二种资格。', '留学申请者须提交日本语学校成绩与出席证明；未设统一百分比。', '["保育科昼间2年","保育科夜间3年","保育士资格","幼稚园教谕二种免许"]'::jsonb, '[{"name":"保育科1部","description":"昼间2年制，留学在留资格者仅可申请此部。","duration":"2年","totalCost":"按2027要项"},{"name":"保育科2部","description":"夜间3年制，留学在留资格者不可申请。","duration":"3年","totalCost":"按2027要项"}]'::jsonb, '{"enrollmentFee":"按2027年度昼间/夜间学费页确认","admissionFee":"按2027年度昼间/夜间学费页确认","annualTuition":"按2027年度昼间/夜间学费页确认","facilitiesFee":"按2027年度昼间/夜间学费页确认","practiceMaterialsFee":"按2027年度昼间/夜间学费页确认","totalFirstYear":"按2027年度昼间/夜间学费页确认"}'::jsonb, '["充分理解毕业后在留资格限制的保育学习者"]'::jsonb, '["学费支援按2027学校页面与个人在留资格确认。"]'::jsonb) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "category" = EXCLUDED."category", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "totalTwoYears" = EXCLUDED."totalTwoYears", "highlights" = EXCLUDED."highlights", "employmentRate" = EXCLUDED."employmentRate", "employmentRateDetail" = EXCLUDED."employmentRateDetail", "paymentTerm" = EXCLUDED."paymentTerm", "degreeAwarded" = EXCLUDED."degreeAwarded", "attendanceRequirement" = EXCLUDED."attendanceRequirement", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "tuitionBreakdownJson" = EXCLUDED."tuitionBreakdownJson", "suitableForJson" = EXCLUDED."suitableForJson", "scholarshipsJson" = EXCLUDED."scholarshipsJson";
DELETE FROM "VocationalSchool" WHERE slug IN ('sundai');
COMMIT;
